// Node: Resolver Tenant
// Fail-closed con selección por texto del mensaje + preferencia persistida.

function normalize(str) {
  return (str || '')
    .toString()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/\b(upp|rancho|granja|finca|propiedad)\b/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

const rawTenants = $json.available_tenants;
let tenants;
if (Array.isArray(rawTenants)) {
  tenants = rawTenants;
} else if (typeof rawTenants === 'string') {
  try {
    const parsed = JSON.parse(rawTenants);
    tenants = Array.isArray(parsed) ? parsed : [];
  } catch (err) {
    tenants = [];
  }
} else {
  tenants = [];
}

const validTenants = tenants.filter(
  (t) => t && typeof t === 'object' && t.id_company !== undefined && t.id_company !== null
);

let tenant_id = null;
let tenant_status;
let tenant_source = null;

const messageText = $json.text || '';
const normalizedMessage = normalize(messageText);
const cachedSelection = $json.selected_tenant_id ? Number($json.selected_tenant_id) : null;

if (validTenants.length === 0) {
  tenant_status = 'none';
} else if (validTenants.length === 1) {
  tenant_id = validTenants[0].id_company;
  tenant_status = 'resolved';
  tenant_source = 'single';
} else {
  const matches = validTenants.filter((t) => {
    const name = normalize(t.company_name);
    return name && normalizedMessage.includes(name);
  });

  if (matches.length === 1) {
    tenant_id = matches[0].id_company;
    tenant_status = 'resolved';
    tenant_source = 'matched_this_message';
  } else if (cachedSelection && validTenants.some((t) => t.id_company === cachedSelection)) {
    tenant_id = cachedSelection;
    tenant_status = 'resolved';
    tenant_source = 'cached';
  } else {
    tenant_status = 'ambiguous';
  }
}

$input.item.json.tenant_id = tenant_id;

const matchedTenant = validTenants.find(t => t.id_company === tenant_id);
$input.item.json.user_email = matchedTenant ? matchedTenant.email : '';

$input.item.json.tenant_status = tenant_status;
$input.item.json.tenant_source = tenant_source;
$input.item.json.available_tenant_names = validTenants.map((t) => t.company_name);

return $input.item;

